appearances.css:
*{letter-spacing:0}
.app{display:flex;flex-wrap:wrap;gap:4px;font-size:9px;align-content:flex-start}
.app>*{flex:1 1 100%;min-width:0}
.bar{gap:3px 6px;align-items:end}
label.sel{gap:1px;font-size:7px;min-width:0}
select,button{font-size:9px;padding:2px 4px;border-radius:3px}
.bar>div[style]{min-width:0!important;flex:0 0 58px!important}
.bar>.k{flex:0 0 58px}
.sec{padding:3px 4px 4px;gap:2px;border-radius:3px}
.sec h4{font-size:8px;letter-spacing:.14em;padding:0 0 1px;border:0}
.app>div:nth-of-type(4){flex:1 1 calc(55.5% - 2px)}
.app>div:nth-of-type(5){flex:1 1 calc(44.5% - 2px)}
.app>div:nth-of-type(6){flex:1 1 calc(77.8% - 2px)}
.app>div:nth-of-type(7){flex:1 1 100%;order:1}
.app>div:nth-of-type(8){flex:1 1 calc(22.2% - 2px)}
.app>canvas,.app>p{order:2}
.knobs{grid-template-columns:repeat(auto-fit,minmax(44px,1fr));gap:3px 0}
.k,.k[style]{display:grid!important;grid-template-columns:minmax(0,1fr)!important;justify-items:center;align-items:start;gap:0;min-width:0}
.k label{order:3;font-size:7px;line-height:1.1;text-align:center;white-space:normal;overflow:visible;text-overflow:clip;max-width:100%}
.k output{order:2;font-size:8px;line-height:1.1;color:var(--muted,#aabec5);white-space:nowrap;text-align:center}
.k .kn{order:1;width:24px!important;height:24px!important;justify-self:center!important}
.k .kn svg{width:100%;height:100%}
.pads{grid-template-columns:repeat(16,minmax(0,1fr));gap:2px}
.pads button{padding:2px 0;font-size:8px}
canvas{height:30px;border-radius:3px}
.note{font-size:8px}
